function best(id,val,lower=false){try{let old=Number(localStorage.getItem('agw-'+id));if(!old||(lower?val<old:val>old))localStorage.setItem('agw-'+id,val);return Number(localStorage.getItem('agw-'+id))}catch{return val}}function render(){let list=games.filter(g=>(filter==='All'||g.cat===filter)&&g.name.toLowerCase().includes(document.querySelector('.search').value.toLowerCase()));grid.innerHTML=list.map(g=>`<article class="card"><button class="cardplay" data-game="${g.id}" aria-label="Play ${g.name}"><div class="thumb" style="background:${g.bg};color:${g.color}"><span class="badge">${g.tag}</span><div class="illustration" style="${g.id==='snake'?'font-size:35px;line-height:.7':''}">${g.art}</div></div><div class="cardinfo"><div class="cardtop"><h3>${g.name}</h3><span class="arrow">↗</span></div><p>${g.desc}</p><div class="meta"><span>${g.cat.toUpperCase()}</span><span>${g.time}</span></div></div></button></article>`).join('')||'<p class="empty">No games found. Try another search.</p>';grid.querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>openGame(b.dataset.game))}render();document.querySelectorAll('.filter').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x===b));render()});document.querySelector('.search').oninput=render;document.querySelector('#surprise').onclick=()=>openGame(games[Math.floor(Math.random()*games.length)].id);document.querySelector('.close').onclick=()=>modal.close();modal.addEventListener('close',()=>{cleanup();lastFocus?.focus()});modal.addEventListener('click',e=>{if(e.target===modal){let r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
function openGame(id){cleanup();cleanup=()=>{};lastFocus=document.activeElement;let g=games.find(g=>g.id===id);document.querySelector('#gameTitle').textContent=g.name;area.innerHTML='';if(!modal.open)modal.showModal();const instructions=document.querySelector('#instructions');const status=()=>area.querySelector('.status');const shell=(html)=>area.innerHTML='<div class="status" aria-live="polite"></div>'+html+'<button class="primary restart">New game ↻</button>';const restart=()=>area.querySelector('.restart').onclick=()=>openGame(id);
if(ArcadeExtras.games.some(g=>g.id===id)){cleanup=ArcadeExtras.mount(id,{area,instructions,shell,status,best});restart();return}
if(id==='ttt'){instructions.textContent='You are X. Choose a square to get three in a row. The computer plays O.';shell('<div class="board" style="grid-template-columns:repeat(3,1fr)">'+Array.from({length:9},(_,i)=>`<button class="cell" aria-label="Square ${i+1}"></button>`).join('')+'</div>');let b=Array(9).fill(''),done=false,timer;const cells=[...area.querySelectorAll('.cell')],win=p=>[[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]].some(l=>l.every(i=>b[i]===p));function end(){if(win('X')||win('O')||b.every(Boolean)){done=true;status().textContent=win('X')?'You win! ✨':win('O')?'Computer wins. Rematch?':'A draw! One more round?';return true}return false}status().textContent='Your turn';cells.forEach((c,i)=>c.onclick=()=>{if(b[i]||done||status().textContent!=='Your turn')return;b[i]='X';c.textContent='X';if(end())return;status().textContent='Computer is thinking…';timer=setTimeout(()=>{let avail=b.map((v,i)=>v?-1:i).filter(i=>i>=0),pick;for(let p of ['O','X']){for(let j of avail){b[j]=p;let yes=win(p);b[j]='';if(yes){pick=j;break}}if(pick!==undefined)break}pick??=avail.includes(4)?4:avail[Math.floor(Math.random()*avail.length)];b[pick]='O';cells[pick].textContent='O';if(!end())status().textContent='Your turn'},350)});cleanup=()=>clearTimeout(timer)}
if(id==='memory'){instructions.textContent='Flip two cards at a time. Match all six pairs in as few moves as possible.';let deck=['🍒','👾','⚡','🌈','⭐','🎮'].flatMap(x=>[x,x]);for(let i=deck.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]]}shell('<div class="board" style="grid-template-columns:repeat(4,1fr)">'+deck.map((x,i)=>`<button class="cell" aria-label="Hidden card ${i+1}">?</button>`).join('')+'</div>');let first=null,locked=false,moves=0,pairs=0,timer;let cells=[...area.querySelectorAll('.cell')];status().textContent='0 moves · 0 / 6 pairs';cells.forEach((c,i)=>c.onclick=()=>{if(locked||c.dataset.open)return;c.textContent=deck[i];c.dataset.open='yes';c.setAttribute('aria-label',deck[i]);if(first===null){first=i;return}moves++;let j=first;first=null;if(deck[i]===deck[j]){pairs++;if(pairs===6){status().textContent=`All matched in ${moves} moves! Best: ${best(id,moves,true)}`;return}}else{locked=true;timer=setTimeout(()=>{[i,j].forEach(k=>{cells[k].textContent='?';delete cells[k].dataset.open;cells[k].setAttribute('aria-label',`Hidden card ${k+1}`)});locked=false},750)}status().textContent=`${moves} moves · ${pairs} / 6 pairs`});cleanup=()=>clearTimeout(timer)}
if(id==='rps'){instructions.textContent='Pick rock, paper, or scissors. Rock beats scissors, scissors beat paper, paper beats rock.';shell('<div class="choices">'+['✊','✋','✌️'].map((x,i)=>`<button aria-label="${['Rock','Paper','Scissors'][i]}">${x}</button>`).join('')+'</div>');let wins=0,rounds=0;status().textContent='Make your move';area.querySelectorAll('.choices button').forEach((b,i)=>b.onclick=()=>{let comp=Math.floor(Math.random()*3),result=(i-comp+3)%3;rounds++;if(result===1)wins++;status().textContent=`Computer: ${['✊','✋','✌️'][comp]} · ${result===0?'Draw!':result===1?'You win!':'Computer wins!'} (${wins}/${rounds} wins)`})}
if(id==='reaction'){instructions.textContent='Click to begin, then wait for green. Click as quickly as you can when the color changes.';shell('<button class="reaction">Click to get ready</button>');let phase='idle',timer,start;const b=area.querySelector('.reaction');b.onclick=()=>{if(phase==='idle'){phase='wait';b.textContent='Wait for green…';b.style.background='#a65a68';timer=setTimeout(()=>{phase='go';start=performance.now();b.style.background='#5b9234';b.textContent='GO! CLICK!'},1500+Math.random()*3000)}else if(phase==='wait'){clearTimeout(timer);phase='idle';b.textContent='Too soon! Click to try again';b.style.background='#7559b3'}else{let ms=Math.round(performance.now()-start);phase='idle';b.textContent=ms+' ms — play again';b.style.background='#7559b3';status().textContent='Personal best: '+best(id,ms,true)+' ms'}};cleanup=()=>clearTimeout(timer)}
if(id==='whack'){instructions.textContent='Tap the mole when it pops up. You have 30 seconds. Hit Start to begin!';shell('<div class="board" style="grid-template-columns:repeat(3,1fr)">'+Array(9).fill('<button class="cell" aria-label="Mole hole">·</button>').join('')+'</div>');let score=0,left=30,pos=-1,active=false,spawn,clock;const cells=[...area.querySelectorAll('.cell')];status().textContent='Ready to whack?';const start=area.querySelector('.restart');start.textContent='Start game';start.onclick=()=>{clearInterval(spawn);clearInterval(clock);score=0;left=30;active=true;start.disabled=true;function pop(){cells.forEach(c=>c.textContent='·');let next;do{next=Math.floor(Math.random()*9)}while(next===pos);pos=next;cells[pos].textContent='🐹'}pop();status().textContent='0 points · 30s';spawn=setInterval(pop,750);clock=setInterval(()=>{left--;status().textContent=`${score} points · ${left}s`;if(left===0){active=false;clearInterval(spawn);clearInterval(clock);cells.forEach(c=>c.textContent='·');status().textContent=`Time! ${score} points · Best: ${best(id,score)}`;start.disabled=false;start.textContent='Play again'}},1000)};cells.forEach((c,i)=>c.onclick=()=>{if(active&&i===pos){score++;pos=-1;c.textContent='✦';status().textContent=`${score} points · ${left}s`}});cleanup=()=>{clearInterval(spawn);clearInterval(clock)};return}
if(id==='snake'){instructions.textContent='Use arrow keys, WASD, or the buttons to steer. Eat pink snacks. Avoid the walls and your tail.';shell('<canvas class="gamecanvas" width="400" height="400" aria-label="Snake game board"></canvas><div class="dpad"><button data-dir="0,-1" aria-label="Up">↑</button><button data-dir="-1,0" aria-label="Left">←</button><button data-dir="0,1" aria-label="Down">↓</button><button data-dir="1,0" aria-label="Right">→</button></div>');let c=area.querySelector('canvas'),ctx=c.getContext('2d'),s=[{x:8,y:10},{x:7,y:10},{x:6,y:10}],dir={x:1,y:0},next={x:1,y:0},food,score=0,dead=false,started=false,timer;function snack(){do{food={x:Math.floor(Math.random()*20),y:Math.floor(Math.random()*20)}}while(s.some(p=>p.x===food.x&&p.y===food.y))}function draw(){ctx.fillStyle='#10131e';ctx.fillRect(0,0,400,400);ctx.strokeStyle='#ffffff08';for(let i=0;i<400;i+=20){ctx.strokeRect(i,0,20,400);ctx.strokeRect(0,i,400,20)}ctx.fillStyle='#f2a0bc';ctx.fillRect(food.x*20+3,food.y*20+3,14,14);s.forEach((p,i)=>{ctx.fillStyle=i?'#91c452':'#c5ff76';ctx.fillRect(p.x*20+2,p.y*20+2,16,16)})}function tick(){dir=next;let h={x:s[0].x+dir.x,y:s[0].y+dir.y},eat=h.x===food.x&&h.y===food.y;let tail=eat?s:s.slice(0,-1);if(h.x<0||h.x>=20||h.y<0||h.y>=20||tail.some(p=>p.x===h.x&&p.y===h.y)){dead=true;clearInterval(timer);status().textContent=`Game over · ${score} points · Best: ${best(id,score)}`;return}s.unshift(h);if(eat){score+=10;if(s.length===400){dead=true;clearInterval(timer);status().textContent='You filled the board! Score: '+score;return}snack()}else s.pop();status().textContent='Score: '+score;draw()}function turn(x,y){if(dead)return;if(x===-dir.x&&y===-dir.y)return;next={x,y};if(!started){started=true;timer=setInterval(tick,140)}}const key=e=>{let map={ArrowUp:[0,-1],w:[0,-1],ArrowDown:[0,1],s:[0,1],ArrowLeft:[-1,0],a:[-1,0],ArrowRight:[1,0],d:[1,0]};if(map[e.key]){e.preventDefault();turn(...map[e.key])}};window.addEventListener('keydown',key);area.querySelectorAll('[data-dir]').forEach(b=>b.onclick=()=>turn(...b.dataset.dir.split(',').map(Number)));snack();draw();status().textContent='Choose a direction to start';cleanup=()=>{clearInterval(timer);window.removeEventListener('keydown',key)}}restart()}
